    "action": "delete",
    "description": "Permission to delete branch records.",
    "allowed": false
  }
]
```

---

## **2. Roles Collection with Permission IDs**

The `roles` collection will store an array of `permissionIds` that reference the `permissions` collection. Each role will inherit the permissions defined by these IDs.

### **Roles Schema**
```javascript
const mongoose = require('mongoose');

const roleSchema = new mongoose.Schema({
    _id: {
        type: mongoose.Schema.Types.ObjectId,
