        ref: 'Permission'
    }]
}, {
    timestamps: true
});

module.exports = mongoose.model('Role', roleSchema);
```

#### How It Works:
- The `set` function is called whenever a value is assigned to the `sport` field.
- The function converts the value to uppercase using `value.toUpperCase()` and stores the transformed value.

---

### **Option 3: Add Validation with a Pre-Save Hook**

If you want to enforce uppercase values but also validate them before saving, you can use a **pre-save middleware** (also known as a "hook"). This approach ensures that the value is both transformed and validated.

#### Updated Schema:
```javascript
const mongoose = require('mongoose');

const roleSchema = new mongoose.Schema({
    _id: {
        type: mongoose.Schema.Types.ObjectId,
        required: true,
        default: mongoose.Types.ObjectId
    },
    name: {
        type: String,
        required: true,
        trim: true
    },
    sport: {
        type: String,
        required: true,
        enum: ['TENNIS', 'FOOTBALL', 'BOTH'],
        trim: true
    },
    description: {
        type: String,
        required: false,
        trim: true
    },
    permissionIds: [{
        type: mongoose.Schema.Types.ObjectId,
        ref: 'Permission'
    }]
}, {
    timestamps: true
});

// Pre-save hook to ensure `sport` is uppercase
roleSchema.pre('save', function (next) {
    if (this.sport) {
        this.sport = this.sport.toUpperCase(); // Convert to uppercase
    }
    next();
});

module.exports = mongoose.model('Role', roleSchema);
```

#### How It Works:
- The `pre('save')` middleware is executed before the document is saved to the database.
- It ensures that the `sport` field is converted to uppercase before saving.
- You can also add additional validation logic here if needed.

---

### **Which Option Should You Choose?**

1. **Use `uppercase: true`**:
   - Simplest and most concise solution.
   - Ideal if you only need to ensure that the value is stored in uppercase without additional logic.

2. **Use a Custom Setter**:
   - Provides flexibility for custom transformations or validations.
   - Useful if you anticipate needing more complex logic in the future.

3. **Use a Pre-Save Hook**:
   - Best for scenarios where you need to enforce uppercase values **and** perform additional validation or transformations.
   - Slightly more verbose but offers the most control.

For your use case, **Option 1 (`uppercase: true`)** is likely the best choice because it’s simple and directly addresses your requirement to store `sport` values in uppercase.

---

### **Example Usage**

Here’s how the schema behaves with the `uppercase` option:

```javascript
