const newRole = new Role({
    name: "Head Coach",
    sport: "tennis", // Lowercase input
    description: "Oversees all coaching activities."
});

newRole.save()
    .then(role => console.log("Saved Role:", role))
    .catch(err => console.error("Error saving role:", err));
```

#### Output:
```json
