## **5. Querying Roles and Permissions**

To retrieve an employee’s roles and permissions, you can use Mongoose’s `.populate()` method to join data from the `roles` and `permissions` collections.

#### **Example Query**
```javascript
const Employee = require('./models/employee.js');
const Role = require('./models/role.js');
const Permission = require('./models/permission.js');

async function getEmployeePermissions(employeeId) {
    try {
        // Step 1: Find the employee and populate their roles
        const employee = await Employee.findById(employeeId).populate('roleIds');

        // Step 2: Extract all permission IDs from the roles
        const permissionIds = employee.roleIds.flatMap(role => role.permissionIds);

        // Step 3: Fetch the permissions using the permission IDs
        const permissions = await Permission.find({ _id: { $in: permissionIds } });

        return permissions;
    } catch (err) {
        console.error("Error fetching employee permissions:", err);
        throw err;
    }
}
```

